                  <option value="" [selected]="!patronChoices()[p.id]">Choose a patron</option>
                  @for (o of patronOptions(p); track o.id) {
                    <option [value]="'' + o.id" [selected]="patronChoices()[p.id] === '' + o.id">{{ o.name }}</option>
